library(optparse)
library(ggplot2)
library(stringr)
library(scales)
library(dplyr)

# generated by copilot
add_ordinal <- function(df) {
  levels <- c("LINE", "LTR", "SegDup", "SINE", "DNA", "Satellite", "Simple", "rRNA", "Other")
  
  df[["ordinal"]] <-
    as.integer(factor(df[["feature"]], levels = levels, ordered = TRUE)) - 1L
  df
}

etl <- function(df) {
  df <- add_ordinal(df)
  df
}

transform_coordinates <- function(df) {
  df$y_start = y_start - (df$ordinal * (y_width + y_space))
  df$y_end = df$y_start + y_width
  df$x_start = 0
  df$x_end = df$megabases
  df
}

# main
option_list <- list(
  make_option(c("-a", "--a"), type = "character", default = NULL,
              help = "Original assembly file path", metavar = "FILE"),
  make_option(c("-b", "--b"), type = "character", default = NULL,
              help = "New assembly file path", metavar = "FILE"),
  make_option(c("-o", "--output"), type = "character", default = "plot.pdf",
              help = "Output file path [default: %default]", metavar = "FILE"),
  make_option(c("-v", "--verbose"), action = "store_true", default = FALSE,
              help = "Print verbose output")
)

opt <- parse_args(OptionParser(option_list = option_list))

if (is.null(opt$a) || is.null(opt$b)) {
  stop("-a and -b are required", call. = FALSE)
}

old <- etl(read.table(opt$a, header=TRUE))
new <- etl(read.table(opt$b, header=TRUE))

delta <- inner_join(old, new, by = "feature")
delta$difference <- sprintf("+%.1f", delta$megabases.y - delta$megabases.x)
print(delta)

y_width = 16
y_space = y_width / 2
y_start = nrow(delta) * (y_width + y_space)

old <- transform_coordinates(old)
new <- transform_coordinates(new)

x_delta_space = 40
delta$y_start = y_start - (delta$ordinal.x * (y_width + y_space))
delta$y_end = delta$y_start + y_width
delta$x <- delta$megabases.y + x_delta_space

x_label_pos = -40

p <- ggplot() + 
      geom_rect(data = new, aes(xmin=x_start, xmax=x_end, ymin=y_end, ymax=y_start), color="black", linewidth = 0.5, fill="lightskyblue") +
      geom_rect(data = old, aes(xmin=x_start, xmax=x_end, ymin=y_end, ymax=y_start), color="black", linewidth = 0.5, fill="lightgrey") +
      geom_text(data = delta, x = x_label_pos, aes(y=(y_end - y_space), label=feature), size=3) +
      geom_text(data = delta, aes(x = x, y=(y_end - y_space), label=difference), size=3) +
      coord_cartesian(xlim = c(x_label_pos, max(new$megabases) + x_delta_space)) + 
      theme_bw() + 
      xlab("Total length (Mbp)") +
      theme(panel.grid = element_blank(),
            panel.border = element_blank(),
            axis.line = element_blank(),
            axis.ticks.y = element_blank(),
            axis.title.y = element_blank(),
            axis.text.y = element_blank()) +
        scale_x_continuous(labels = comma)
  

ggsave(opt$out, p, units="px", width=2000, height=750)
